<script setup>
import { computed, ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
import EmptyState from '../../../Components/Ui/EmptyState.vue';
import EmployeeSheet from '../../../Components/StaffMeals/EmployeeSheet.vue';

defineOptions({layout:AdminLayout});
const props=defineProps({employees:{type:Array,default:()=>[]},categories:{type:Array,default:()=>[]},urls:{type:Object,required:true},employeeForm:{type:Object,default:()=>({})}});
const activeCategory=ref(props.categories[0]?.id??null);const search=ref('');
const employeeOpen=ref(false);
const form=useForm({employee_id:'',lines:[],notes:'',is_gift:false,gift_reason:''});
const selectedEmployee=computed(()=>props.employees.find(e=>String(e.id)===String(form.employee_id)));
const visibleCategories=computed(()=>props.categories.map(category=>({...category,items:category.items.filter(item=>!search.value.trim()||item.name.includes(search.value.trim()))})).filter(category=>category.items.length));
const total=computed(()=>form.lines.reduce((sum,line)=>sum+Number(line.price)*Number(line.quantity),0));
const covered=computed(()=>form.is_gift?total.value:Math.min(total.value,Number(selectedEmployee.value?.remaining||0)));
const employeeDue=computed(()=>form.is_gift?0:Math.max(0,total.value-covered.value));
function add(item){if(!item.available)return;const line=form.lines.find(row=>row.menu_item_id===item.id);if(line)line.quantity=Math.min(99,Number(line.quantity)+1);else form.lines.push({menu_item_id:item.id,name:item.name,price:item.price,priceFormatted:item.priceFormatted,quantity:1})}
function remove(index){form.lines.splice(index,1)}
function submit(){form.transform(data=>({...data,is_gift:data.is_gift?1:0,lines:data.lines.map(({menu_item_id,quantity})=>({menu_item_id,quantity}))})).post(props.urls.store,{preserveScroll:true})}
</script>
<template>
<Head title="استهلاك موظف"/>
<PageHeader title="تسجيل استهلاك موظف" icon="bi-cup-straw" subtitle="اختر الموظف والأصناف؛ لا يشترط أن يكون للعامل حساب دخول" :crumbs="[{label:'بدل الوجبات',url:urls.index}]"><template #actions><button type="button" class="btn btn-light" @click="employeeOpen=true"><i class="bi bi-person-plus"></i> موظف جديد</button></template></PageHeader>
<section v-if="selectedEmployee&&form.lines.length" class="allocation"><span><small>قيمة الوجبة</small><b>{{total.toFixed(2)}} ش.إ</b></span><span><small>ضمن البدل</small><b>{{covered.toFixed(2)}} ش.إ</b></span><span :class="{due:employeeDue>0}"><small>على الموظف</small><b>{{employeeDue.toFixed(2)}} ش.إ</b></span><p>المتبقي قبل هذه الوجبة: {{selectedEmployee.remainingFormatted}}</p></section>
<div v-if="employees.length" class="consume-layout"><main><section class="picker-head"><label><i class="bi bi-search"></i><input v-model="search" placeholder="ابحث عن صنف…"></label><div><button v-for="category in categories" :key="category.id" type="button" :class="{active:activeCategory===category.id}" @click="activeCategory=category.id">{{category.name}} <b>{{category.items.length}}</b></button></div></section><div class="categories"><section v-for="category in visibleCategories" v-show="!activeCategory||activeCategory===category.id||search" :key="category.id"><header><h2>{{category.name}}</h2><span>{{category.items.length}} صنفاً</span></header><div class="items"><button v-for="item in category.items" :key="item.id" type="button" :disabled="!item.available" @click="add(item)"><span class="item-icon">{{item.name[0]}}</span><span><strong>{{item.name}}</strong><small v-if="item.available">{{item.priceFormatted}}</small><small v-else class="unavailable">غير متوفر اليوم</small></span><i class="bi" :class="item.available?'bi-plus-lg':'bi-slash-circle'"></i></button></div></section><EmptyState v-if="!visibleCategories.length" icon="bi-search" title="لا يوجد صنف مطابق" message="جرّب كلمة أخرى أو امسح البحث."/></div></main>
<aside><section class="cart"><header><div><small>الموظف</small><h2>{{selectedEmployee?.name||'اختر الموظف'}}</h2></div><span>{{form.lines.reduce((s,l)=>s+Number(l.quantity),0)}}</span></header><label class="employee"><span>الموظف *</span><select v-model="form.employee_id" required><option value="">اختر الموظف</option><option v-for="employee in employees" :key="employee.id" :value="employee.id">{{employee.name}} · {{employee.hasLogin?'له دخول':'بدون دخول'}} · حد {{employee.allowance}}</option></select><small v-if="form.errors.employee_id">{{form.errors.employee_id}}</small></label><div v-if="form.lines.length" class="lines"><article v-for="(line,index) in form.lines" :key="line.menu_item_id"><div><strong>{{line.name}}</strong><small>{{line.priceFormatted}} × {{line.quantity}}</small></div><div class="quantity"><button type="button" @click="line.quantity>1?line.quantity--:remove(index)">−</button><input v-model="line.quantity" type="number" min="1" max="99"><button type="button" @click="line.quantity=Math.min(99,Number(line.quantity)+1)">+</button></div><button type="button" class="remove" @click="remove(index)"><i class="bi bi-trash3"></i></button></article></div><div v-else class="empty-cart"><i class="bi bi-bag-plus"></i><strong>لم تختر أصنافاً</strong><small>اضغط + على الأصناف التي أخذها الموظف.</small></div><div class="total"><span>الإجمالي</span><strong>{{total.toFixed(2)}} ش.إ</strong></div><label class="gift"><input v-model="form.is_gift" type="checkbox"><span><i class="bi bi-gift-fill"></i></span><div><strong>هدية للموظف</strong><small>لا تُضاف على بدله وتُسجّل كمنفعة موظف.</small></div></label><input v-if="form.is_gift" v-model="form.gift_reason" class="note" maxlength="300" placeholder="سبب الهدية (اختياري)"><input v-model="form.notes" class="note" maxlength="500" placeholder="ملاحظة داخلية (اختياري)"><button class="submit" type="button" :class="{gifted:form.is_gift}" :disabled="form.processing||!form.employee_id||!form.lines.length" @click="submit"><i class="bi" :class="form.is_gift?'bi-gift-fill':'bi-check2-circle'"></i>{{form.processing?'جارٍ التسجيل…':form.is_gift?'تسجيل الهدية':'تسجيل على بدل الموظف'}}</button></section></aside></div>
<section v-else class="no-employees"><EmptyState icon="bi-person-plus" title="لا يوجد موظفون لهم بدل مفعّل" message="أضف الموظف هنا؛ لا حاجة لإنشاء اسم مستخدم أو كلمة مرور."><template #cta><button type="button" class="btn btn-primary" @click="employeeOpen=true">إضافة موظف</button></template></EmptyState></section>
<EmployeeSheet :open="employeeOpen" :store-url="urls.employeesStore" :options="employeeForm" @close="employeeOpen=false" />
</template>
<style scoped>
.allocation{display:grid;grid-template-columns:repeat(3,minmax(120px,1fr)) auto;align-items:center;gap:.5rem;margin:0 0 .8rem;padding:.65rem .8rem;border:1px solid #cfe4d7;border-radius:13px;background:#f5faf7}.allocation span{display:grid;gap:.1rem;padding:.4rem .55rem;border-inline-end:1px solid #dce9e1}.allocation small{color:#73837a;font-size:.61rem}.allocation b{font-size:.75rem;color:#156f43}.allocation .due b{color:#b56a0b}.allocation p{margin:0;color:#6c7d73;font-size:.62rem}@media(max-width:680px){.allocation{grid-template-columns:1fr 1fr 1fr}.allocation p{grid-column:1/-1}}
.consume-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:1rem;align-items:start}.picker-head,.categories section,.cart{background:#fff;border:1px solid #dce6e0;border-radius:15px}.picker-head{padding:.75rem;margin-bottom:.75rem}.picker-head label{display:flex;align-items:center;gap:.5rem;border:1px solid #dce5df;border-radius:10px;padding:0 .7rem}.picker-head input{width:100%;min-height:42px;border:0;outline:0}.picker-head>div{display:flex;gap:.35rem;overflow-x:auto;margin-top:.55rem}.picker-head>div button{border:1px solid #dfe7e2;background:#fff;border-radius:99px;padding:.4rem .65rem;white-space:nowrap;font-size:.68rem}.picker-head>div button.active{background:#137443;color:#fff;border-color:#137443}.picker-head button b{padding:.08rem .3rem;background:rgba(255,255,255,.18);border-radius:99px}.categories{display:grid;gap:.7rem}.categories section{overflow:hidden}.categories section header{display:flex;justify-content:space-between;padding:.75rem 1rem;border-bottom:1px solid #e9efeb}.categories h2{font-size:.82rem;margin:0}.categories header span{font-size:.65rem;color:#829188}.items{display:grid;grid-template-columns:repeat(2,1fr);gap:.45rem;padding:.65rem}.items>button{display:grid;grid-template-columns:38px 1fr 28px;gap:.55rem;align-items:center;text-align:start;border:1px solid #e0e8e3;background:#fff;border-radius:11px;padding:.55rem}.items>button:hover:not(:disabled){border-color:#63ae82;background:#f4faf6}.items>button:disabled{opacity:.55}.item-icon{width:38px;height:38px;border-radius:10px;background:#eaf5ee;color:#0f713f;display:grid;place-items:center;font-weight:900}.items button>span:nth-child(2){display:grid}.items strong{font-size:.72rem}.items small{font-size:.64rem;color:#167343}.items .unavailable{color:#ad4949}.items button>i{width:28px;height:28px;border-radius:8px;background:#eff7f2;color:#107140;display:grid;place-items:center}.cart{position:sticky;top:88px;overflow:hidden}.cart>header{display:flex;justify-content:space-between;align-items:center;padding:.85rem 1rem;background:#f0f7f3;border-bottom:1px solid #dce8e0}.cart h2,.cart small{margin:0}.cart h2{font-size:.9rem}.cart header small{font-size:.64rem;color:#819087}.cart header>span{width:30px;height:30px;border-radius:9px;background:#137443;color:#fff;display:grid;place-items:center;font-size:.7rem;font-weight:900}.employee{display:grid;gap:.3rem;padding:.75rem 1rem}.employee>span{font-size:.7rem;font-weight:800}.employee select,.note{border:1px solid #dce5df;border-radius:10px;padding:.55rem;background:#fff}.employee small{color:#b63b3b;font-size:.64rem}.lines{padding:.25rem .75rem;max-height:340px;overflow-y:auto}.lines article{display:grid;grid-template-columns:1fr 94px 28px;align-items:center;gap:.45rem;padding:.55rem 0;border-top:1px solid #edf1ef}.lines article>div:first-child{display:grid}.lines strong{font-size:.7rem}.lines small{font-size:.62rem;color:#819087}.quantity{display:grid;grid-template-columns:28px 36px 28px;border:1px solid #dce5df;border-radius:8px;overflow:hidden}.quantity button{border:0;background:#f1f6f3;color:#117140}.quantity input{border:0;text-align:center;min-width:0;font-size:.7rem}.remove{border:0;background:none;color:#bd3d3d}.empty-cart{text-align:center;padding:1.5rem;color:#7b8b82;display:grid;gap:.25rem}.empty-cart i{font-size:1.3rem}.empty-cart strong{font-size:.75rem}.empty-cart small{font-size:.65rem}.total{display:flex;justify-content:space-between;padding:.8rem 1rem;border-block:1px solid #e9efeb;background:#fbfcfb}.total span{font-size:.72rem}.total strong{color:#0f713f}.gift{display:grid;grid-template-columns:auto 38px 1fr;align-items:center;gap:.55rem;margin:.75rem 1rem;padding:.65rem;border:1px solid #cce4d5;background:#f3faf5;border-radius:10px}.gift>span{width:34px;height:34px;border-radius:9px;background:#dff1e6;color:#147443;display:grid;place-items:center}.gift>div{display:grid}.gift strong{font-size:.7rem}.gift small{font-size:.61rem;color:#718279}.note{display:block;width:calc(100% - 2rem);margin:.45rem 1rem;font-size:.7rem}.submit{width:calc(100% - 2rem);min-height:48px;margin:.55rem 1rem 1rem;border:0;border-radius:11px;background:#137443;color:#fff;font-weight:850}.submit.gifted{background:#1a8c54}.submit:disabled{opacity:.5}.no-employees{background:#fff;border:1px solid #dce6e0;border-radius:15px}@media(max-width:900px){.consume-layout{grid-template-columns:1fr}.cart{position:static}.items{grid-template-columns:repeat(3,1fr)}}@media(max-width:680px){.items{grid-template-columns:1fr 1fr}.consume-layout{gap:.65rem}.cart{border-radius:13px}.submit{position:sticky;bottom:.5rem;box-shadow:0 8px 24px rgba(0,0,0,.15)}}@media(max-width:440px){.items{grid-template-columns:1fr}.picker-head,.categories section{border-radius:12px}}
</style>
